const SPIDERWEB_PAGE="<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#0a172b\">\n<title>Saturday Morning Spider Web · Tabor World</title>\n<style>\n:root{font:16px/1.5 system-ui,-apple-system,sans-serif;color:#eef4ff;background:#081528;color-scheme:dark}*{box-sizing:border-box}body{margin:0}a{color:#a7e9ff}button,input,select{font:inherit}button{cursor:pointer;border-radius:10px;background:#19334c;color:#eaf4ff;border:1px solid #55748c;padding:8px 12px}button:hover{background:#27506c}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #ffe096;outline-offset:2px}\nmain{max-width:1510px;margin:auto;padding:20px 18px 90px}nav{display:flex;gap:12px;flex-wrap:wrap;align-items:center}nav a{text-decoration:none;border:1px solid #53677d;border-radius:9px;padding:7px 12px}\nheader{background:radial-gradient(circle at 85% 5%,#503b73,transparent 44%),linear-gradient(120deg,#173956,#0d2736);border:1px solid #516d87;border-radius:22px;padding:28px;margin:20px 0}\nh1{font-size:clamp(2rem,6vw,4.5rem);line-height:1.04;margin:10px 0}h2{font-size:1.4rem;margin:20px 0 8px}h3{margin:8px 0}.eyebrow{color:#f5d88e;font-weight:800;letter-spacing:.13em;font-size:.8rem}.muted{color:#c0d2e5}.small{font-size:.86rem}.stats{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.stats span{padding:6px 12px;border:1px solid #65778b;border-radius:40px}\n.toolbar{display:flex;flex-wrap:wrap;gap:9px;align-items:center;margin:15px 0}.toolbar input{min-width:210px;flex:1;max-width:450px}input,select{background:#0d2135;color:#fff;border:1px solid #617e92;border-radius:9px;padding:10px}\n.chips{display:flex;gap:7px;flex-wrap:wrap;margin:13px 0}.chips button{font-size:.83rem;padding:7px 10px}.chips button[aria-pressed=true],button.primary{background:#eed18e;color:#15283a;border-color:#eed18e;font-weight:800}\n.layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(260px,350px);gap:14px;align-items:start}.panel{background:#11283f;border:1px solid #45627a;border-radius:16px;padding:16px;min-width:0}.graphbox{height:clamp(410px,61vw,720px);background:radial-gradient(circle at center,#173d53,#0b1b31 67%);border:1px solid #45627a;border-radius:14px;overflow:hidden;touch-action:pan-y}.graphbox svg{display:block;width:100%;height:100%}.graphbox svg .edge{stroke:#52748b;stroke-width:2;opacity:.6}.graphbox svg .cross{stroke:#a1a5d2;stroke-dasharray:8 9;opacity:.38}.graphbox svg .path{stroke:#ffda7d;stroke-width:5;opacity:.9}.graphbox svg .n{cursor:pointer;stroke:#d5f1ff;stroke-width:2}.graphbox svg .n:focus{stroke:#ffe096;stroke-width:5;outline:none}.graphbox svg .selected{stroke:#fff2a0;stroke-width:5}.graphbox svg text{fill:#e5efff;font-size:17px;font-weight:700;pointer-events:none;text-anchor:middle;paint-order:stroke;stroke:#08182c;stroke-width:4px;stroke-linejoin:round}\n.detail p{margin:10px 0}.detail strong{color:#f2d58e}.detail .row{border-top:1px solid #466077;padding:9px 0}.row button{font-size:.84rem;padding:6px 9px}.results{max-height:420px;overflow:auto}.result{width:100%;text-align:left;display:block;margin:7px 0}.result small{display:block;color:#bfd1e1}.controls{display:flex;gap:9px;flex-wrap:wrap}.path-controls{display:grid;grid-template-columns:1fr 1fr;gap:10px}.path-controls select{min-width:0;width:100%}.path-controls label{font-weight:700;font-size:.83rem}.path-controls label select{display:block;margin-top:6px}.path-text{padding:12px;background:#1a354c;border-left:4px solid #f0d38c;border-radius:8px;min-height:54px}\n.formula-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px}.formula{padding:12px;background:#152d44;border:1px solid #4b6b80;border-radius:12px}.formula small{color:#efcf89}.formula strong{display:block}.formula p{font-size:.8rem;color:#c3d4e5;margin:5px 0}\n.note{border-left:4px solid #e4bd78;padding:12px 16px;background:#1c2f42;border-radius:9px;margin:20px 0}\nfooter{border-top:1px solid #456176;margin-top:30px;padding:18px 0;color:#bed0df}\n@media(max-width:950px){.layout{grid-template-columns:1fr}.graphbox{height:470px}.detail{min-height:190px}}@media(max-width:500px){main{padding:14px 10px 55px}header{padding:18px}.graphbox{height:380px}.path-controls{grid-template-columns:1fr}}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n</style></head><body><main>\n<nav aria-label=\"Navigation\"><strong>🕸 TABOR WORLD</strong><a href=\"/\">Saturday Morning Studio</a><a href=\"https://tabor-world.nathantaboract.workers.dev/\">World Gateway</a><a href=\"/#studio\">Rewrite Studio</a><a href=\"#formula-section\">33 Formulas</a></nav>\n<header><div class=\"eyebrow\">BY NATHAN TABOR · RECOVERED SOURCE WEB · ORIGINAL-ONLY PUBLIC VIEW</div><h1>The Saturday Morning<br>Spider Web</h1><p class=\"muted\">Follow every connection without collapsing one world into another. Recovered material, author recollections, prototypes and new story concepts remain visibly different.</p><div class=\"stats\"><span id=\"count-nodes\">Loading…</span><span id=\"count-edges\">Connections</span><span>33 indexed creative formulas</span><span>22 × 26 = 572 family slots</span></div></header>\n<div class=\"note\"><strong>What this map is:</strong> A navigable provenance and creative-connection atlas. It is not a claim that every planned book is written, every game is built, or that creative equations are validated physics. Third-party characters, logos and artwork are excluded.</div>\n<section aria-label=\"Explore the connections\"><h2>Explore the web</h2><div class=\"toolbar\"><label for=\"search\">Find any connection</label><input id=\"search\" type=\"search\" placeholder=\"e.g. Southern, HO BO BOW, TaborTales, novella\"><button id=\"expand\" aria-pressed=\"false\">Expand all nodes</button><button id=\"zoom-in\" aria-label=\"Zoom in\">+</button><button id=\"zoom-out\" aria-label=\"Zoom out\">−</button><button id=\"reset-view\">Reset view</button><button id=\"export-graph\">Export web JSON</button></div><div id=\"chips\" class=\"chips\" aria-label=\"Branch filters\"></div>\n<div class=\"layout\"><div class=\"panel\"><div class=\"graphbox\"><svg id=\"graph\" viewBox=\"0 0 1800 1300\" role=\"img\" aria-label=\"Interactive spiderweb of Saturday Morning World. Use the searchable node list below for accessible navigation.\"><g id=\"graph-edges\"></g><g id=\"graph-nodes\"></g></svg></div><p class=\"small muted\">Tap a circle to inspect a connection. Use the branch filters, search, zoom controls or the complete text list. Solid lines are family links; dotted lines are crossovers.</p>\n<h3>Find a route between two ideas</h3><div class=\"path-controls\"><label>From<select id=\"path-from\"></select></label><label>To<select id=\"path-to\"></select></label></div><div class=\"controls\" style=\"margin:12px 0\"><button class=\"primary\" id=\"find-path\">Trace connection</button><button id=\"clear-path\">Clear route</button></div><div id=\"path-text\" class=\"path-text\" role=\"status\">Choose two ideas and trace their connection.</div></div>\n<aside class=\"panel\"><h3>Selected source</h3><div id=\"detail\" class=\"detail\" aria-live=\"polite\"></div><h3>Searchable nodes</h3><p class=\"small muted\" id=\"result-count\"></p><div id=\"results\" class=\"results\"></div></aside></div></section>\n<section id=\"formula-section\"><h2>The 33 creative formulas</h2><p class=\"muted\">Recovered from a four-block formula document. These are preserved as <strong>creative, metaphorical or speculative constructions</strong>, not independently verified scientific equations. Public labels avoid protected fictional names.</p><div class=\"chips\" id=\"formula-chips\"></div><div class=\"formula-grid\" id=\"formulas\"></div></section>\n<section><h2>Where to write and play next</h2><div class=\"controls\"><a href=\"/#studio\">Open local Rewrite Studio</a><a href=\"/#signal-game\">Play Signal Switchboard</a><a href=\"https://grapple-it.nathantaboract.workers.dev/\">Play Grapple It</a><a href=\"https://tabor-tracker-ball.nathantaboract.workers.dev/\">Open Tabor Tracker Ball</a></div><p class=\"muted\">Your private source documents and correspondence are not published by this web page. Local drafts remain on the device where they were saved until you export them.</p></section>\n<footer>Saturday Morning World · 1+1=2 BUILD · 1−1=0 CLEAR · Innocence is not a commodity. Original stories and distinct sources stay distinct.</footer>\n</main>\n<script>\n'use strict';\nconst $=id=>document.getElementById(id);\nlet data={nodes:[],edges:[],formulas:[]},nodeMap=new Map(),selected='root',active='all',expanded=false,search='',formulaBlock='All',route=[],scale=1,panX=0,panY=0;\nconst colors={root:'#ffdd88',origins:'#84c9dd',southern:'#f2a67a',team:'#c9b2f6',cartoon:'#f4cf83',word:'#8dd7bb',books:'#e9b5d5',worlds:'#a8c989',games:'#8ab1fa',signal:'#e5aa8d',values:'#f3d37d',sources:'#a7c5d5'};\nfunction el(tag,text,cls){const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x}\nfunction nodeGroup(n){return n.id==='root'?'root':n.parent==='root'?n.id:n.parent}\nfunction setSelected(id){if(!nodeMap.has(id))return;selected=id;const n=nodeMap.get(id);if(n.parent&&n.parent!=='root')active=n.parent;render()}\nfunction positions(){const p=new Map([['root',{x:900,y:650}]]);const groups=data.nodes.filter(n=>n.parent==='root');groups.forEach((g,i)=>{const angle=-Math.PI/2+i*Math.PI*2/groups.length;p.set(g.id,{x:900+350*Math.cos(angle),y:650+350*Math.sin(angle)});const children=data.nodes.filter(n=>n.parent===g.id);children.forEach((n,j)=>{const offset=(j-(children.length-1)/2)*Math.min(.15,.53/Math.max(1,children.length-1));const r=505+(j%3)*46;p.set(n.id,{x:900+r*Math.cos(angle+offset),y:650+r*Math.sin(angle+offset)})})});return p}\nfunction visible(){const ids=new Set(['root',...data.nodes.filter(n=>n.parent==='root').map(n=>n.id)]);for(const n of data.nodes){if(n.parent&&n.parent!=='root'&&(expanded||active===n.parent||search&&[n.label,n.summary,n.source].join(' ').toLowerCase().includes(search.toLowerCase())||n.id===selected||route.includes(n.id)))ids.add(n.id)}return ids}\nfunction renderGraph(){const ns=$('graph-nodes'),es=$('graph-edges'),svg=$('graph'),p=positions(),shown=visible();ns.replaceChildren();es.replaceChildren();const activeEdges=new Set();for(let i=0;i<route.length-1;i++){const a=route[i],b=route[i+1];activeEdges.add([a,b].sort().join('|'))}for(const e of data.edges){if(!shown.has(e.from)||!shown.has(e.to))continue;const a=p.get(e.from),b=p.get(e.to);if(!a||!b)continue;const line=document.createElementNS('http://www.w3.org/2000/svg','line');for(const [k,v] of Object.entries({x1:a.x,y1:a.y,x2:b.x,y2:b.y}))line.setAttribute(k,String(v));line.setAttribute('class','edge '+(e.relation==='contains'?'':'cross')+(activeEdges.has([e.from,e.to].sort().join('|'))?' path':''));es.append(line)}for(const n of data.nodes){if(!shown.has(n.id))continue;const pos=p.get(n.id);if(!pos)continue;const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.setAttribute('transform','translate('+pos.x+','+pos.y+')');const circle=document.createElementNS('http://www.w3.org/2000/svg','circle');circle.setAttribute('r',String(n.id==='root'?27:n.parent==='root'?19:10));circle.setAttribute('fill',colors[nodeGroup(n)]||'#9dd1df');circle.setAttribute('class','n'+(n.id===selected?' selected':''));circle.setAttribute('tabindex','0');circle.setAttribute('role','button');circle.setAttribute('aria-label',n.label);circle.addEventListener('click',()=>setSelected(n.id));circle.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setSelected(n.id)}});const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=n.label;circle.append(title);g.append(circle);if(n.id==='root'||n.parent==='root'||n.id===selected){const t=document.createElementNS('http://www.w3.org/2000/svg','text');t.setAttribute('y',n.id==='root'?-42:-25);t.textContent=n.label.length>30?n.label.slice(0,29)+'…':n.label;g.append(t)}ns.append(g)}const w=1800/scale,h=1300/scale;svg.setAttribute('viewBox',[(1800-w)/2-panX,(1300-h)/2-panY,w,h].join(' '))}\nfunction renderChips(){const host=$('chips');host.replaceChildren();for(const g of [{id:'all',label:'All branches'},...data.nodes.filter(n=>n.parent==='root').map(n=>({id:n.id,label:n.label}))]){const b=el('button',g.label);b.type='button';b.setAttribute('aria-pressed',String(active===g.id));b.onclick=()=>{active=g.id;render()};host.append(b)}}\nfunction renderDetail(){const n=nodeMap.get(selected)||nodeMap.get('root'),d=$('detail');d.replaceChildren();d.append(el('h3',n.label),el('p',n.summary));const stage=el('p','Evidence stage: '+n.stage);stage.className='small';d.append(stage,el('p','Source: '+n.source,'small'));if(n.link){const a=el('a','Open linked work');a.href=n.link;d.append(a)}const relations=data.edges.filter(e=>e.from===n.id||e.to===n.id).slice(0,24);if(relations.length){d.append(el('h3','Direct connections'));for(const e of relations){const other=nodeMap.get(e.from===n.id?e.to:e.from);if(!other)continue;const r=el('div',undefined,'row'),b=el('button',other.label);b.onclick=()=>setSelected(other.id);r.append(b,el('span',' · '+e.relation,'small'));d.append(r)}}}\nfunction renderResults(){const q=search.toLowerCase(),arr=data.nodes.filter(n=>(active==='all'||n.id===active||n.parent===active||n.id==='root')&&[n.label,n.summary,n.source,n.stage].join(' ').toLowerCase().includes(q));$('result-count').textContent=arr.length+' matching nodes';const host=$('results');host.replaceChildren();for(const n of arr){const b=el('button',n.label,'result');const s=el('small',n.stage+' · '+n.source);b.append(s);b.onclick=()=>setSelected(n.id);host.append(b)}}\nfunction render(){renderChips();renderGraph();renderDetail();renderResults();$('expand').setAttribute('aria-pressed',String(expanded));$('expand').textContent=expanded?'Collapse to key nodes':'Expand all nodes'}\nfunction pathFind(a,b){const adj=new Map(data.nodes.map(n=>[n.id,[]]));for(const e of data.edges){adj.get(e.from)?.push(e.to);adj.get(e.to)?.push(e.from)}const q=[a],prev=new Map([[a,null]]);for(let i=0;i<q.length;i++){const cur=q[i];if(cur===b)break;for(const next of adj.get(cur)||[])if(!prev.has(next)){prev.set(next,cur);q.push(next)}}if(!prev.has(b))return [];const out=[];for(let cur=b;cur!==null;cur=prev.get(cur))out.push(cur);return out.reverse()}\nfunction drawFormula(){const blocks=['All','Spatial Folding','Zigzag Dynamics','Antenna & Scripture','Labels & Archetypes'];const host=$('formula-chips');host.replaceChildren();for(const block of blocks){const b=el('button',block);b.setAttribute('aria-pressed',String(block===formulaBlock));b.onclick=()=>{formulaBlock=block;drawFormula()};host.append(b)}const cards=$('formulas');cards.replaceChildren();for(const f of data.formulas.filter(x=>formulaBlock==='All'||x.block===formulaBlock)){const c=el('article',undefined,'formula');c.append(el('small',f.id+' · '+f.block),el('strong',f.label),el('p','Creative archive entry — not validated physics.'));cards.append(c)}}\nfunction populatePaths(){for(const id of ['path-from','path-to']){const s=$(id);s.replaceChildren();for(const n of data.nodes){const opt=el('option',n.label);opt.value=n.id;s.append(opt)}}$('path-from').value='sound-chain';$('path-to').value='grapple'}\n$('search').addEventListener('input',e=>{search=e.target.value.trim();render()});$('expand').onclick=()=>{expanded=!expanded;render()};$('zoom-in').onclick=()=>{scale=Math.min(3,scale*1.3);renderGraph()};$('zoom-out').onclick=()=>{scale=Math.max(.7,scale/1.3);renderGraph()};$('reset-view').onclick=()=>{scale=1;panX=0;panY=0;renderGraph()};\n$('find-path').onclick=()=>{route=pathFind($('path-from').value,$('path-to').value);expanded=true;const labels=route.map(id=>nodeMap.get(id)?.label||id);$('path-text').textContent=labels.length?labels.join(' → '):'No connection found.';if(route.length){selected=route[route.length-1];active='all'}render()};\n$('clear-path').onclick=()=>{route=[];$('path-text').textContent='Route cleared.';render()};\n$('export-graph').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tabor-saturday-morning-spiderweb.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};\nasync function init(){try{const r=await fetch('/api/spiderweb');if(!r.ok)throw Error('HTTP '+r.status);data=await r.json();nodeMap=new Map(data.nodes.map(n=>[n.id,n]));$('count-nodes').textContent=data.nodes.length+' linked nodes';$('count-edges').textContent=data.edges.length+' source & crossover connections';populatePaths();drawFormula();render();const hash=decodeURIComponent(location.hash.slice(1));if(hash.startsWith('node=')&&nodeMap.has(hash.slice(5)))setSelected(hash.slice(5))}catch(err){$('detail').textContent='Could not load graph data: '+String(err);$('count-nodes').textContent='Graph unavailable'}}\ninit();\n</script></body></html>";
addEventListener('fetch',e=>e.respondWith(handle(e.request)));
function json(req,value,status=200){return new Response(req.method==='HEAD'?null:JSON.stringify(value),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','referrer-policy':'no-referrer'}})}
async function handle(req){const path=new URL(req.url).pathname;const headers={'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','referrer-policy':'no-referrer','content-security-policy':"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; object-src 'none'; img-src 'none'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"};if(!['GET','HEAD'].includes(req.method))return new Response('Method not allowed',{status:405,headers:{...headers,allow:'GET, HEAD'}});if(path==='/health')return json(req,{ok:true,app:'tabor-world-saturday-morning',release:'1.2.0',spiderwebNodes:SPIDERWEB_DATA.nodes.length,spiderwebEdges:SPIDERWEB_DATA.edges.length,formulas:SPIDERWEB_DATA.formulas.length,families:FAMILIES.length,letters:26,primarySlots:FAMILIES.length*26,ledgerEntries:LEDGER.length,localOnly:true});if(path==='/api/families')return json(req,{families:FAMILIES,letters:'ABCDEFGHIJKLMNOPQRSTUVWXYZ',primarySlots:FAMILIES.length*26});if(path==='/api/ledger')return json(req,LEDGER);if(path==='/api/spiderweb')return json(req,SPIDERWEB_DATA);if(path==='/api/formulas')return json(req,SPIDERWEB_DATA.formulas);if(path==='/spiderweb')return new Response(req.method==='HEAD'?null:SPIDERWEB_PAGE,{headers});if(path!=='/')return new Response('Not found',{status:404,headers});return new Response(req.method==='HEAD'?null:PAGE,{headers})}
